export type DataRow = {
  id: string;
  /** The heading of the row: a day, a category, a step. */
  label: string;
  cells: readonly string[];
};

type DataTableProps = {
  caption: string;
  /** The heading of the label column first, then one per cell. */
  columns: readonly string[];
  rows: readonly DataRow[];
};

/**
 * The numbers a chart draws, as a table for screen readers. It is taken out of the flow, so the
 * piece it sits in has to be positioned: a hidden box inside an area that scrolls sideways widens
 * the page otherwise.
 */
export function DataTable({ caption, columns, rows }: DataTableProps) {
  return (
    <table className='sr-only'>
      <caption>{caption}</caption>
      <thead>
        <tr>
          {columns.map((column) => (
            <th key={column} scope='col'>
              {column}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row.id}>
            <th scope='row'>{row.label}</th>
            {row.cells.map((cell, index) => (
              <td key={index}>{cell}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

const LOCALE = 'en-US';

export const COUNT_FORMAT: Intl.NumberFormatOptions = {
  maximumFractionDigits: 0,
};

export const SIGNED_FORMAT: Intl.NumberFormatOptions = {
  maximumFractionDigits: 0,
  signDisplay: 'exceptZero',
};

export const USD_COMPACT_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  notation: 'compact',
  maximumFractionDigits: 1,
};

const COMPACT_FORMAT: Intl.NumberFormatOptions = {
  notation: 'compact',
  maximumFractionDigits: 1,
};

const COUNT = new Intl.NumberFormat(LOCALE, COUNT_FORMAT);

const SIGNED = new Intl.NumberFormat(LOCALE, SIGNED_FORMAT);

const COMPACT = new Intl.NumberFormat(LOCALE, COMPACT_FORMAT);

const USD_COMPACT = new Intl.NumberFormat(LOCALE, USD_COMPACT_FORMAT);

const DAY = new Intl.DateTimeFormat(LOCALE, {
  month: 'short',
  day: 'numeric',
  timeZone: 'UTC',
});

const MS_PER_DAY = 86_400_000;

export function formatCount(value: number) {
  return COUNT.format(value);
}

export function formatSigned(value: number) {
  return SIGNED.format(value);
}

export function formatCompact(value: number) {
  return COMPACT.format(value);
}

export function formatUsd(value: number) {
  return USD_COMPACT.format(value);
}

export function formatShare(share: number) {
  const percent = Math.round(share * 100);
  return `${percent}%`;
}

/** A start at zero has no percentage to grow from: it reads as no change. */
export function percentChangeOf(current: number, previous: number) {
  if (previous === 0) {
    return 0;
  }
  const difference = current - previous;
  const ratio = difference / Math.abs(previous);
  return Math.round(ratio * 100);
}

export function changeWordsOf(percent: number, reference: string) {
  if (percent === 0) {
    return `level with ${reference}`;
  }
  const size = Math.abs(percent);
  if (percent > 0) {
    return `up ${size}% on ${reference}`;
  }
  return `down ${size}% on ${reference}`;
}

export function nounOf(count: number, singular: string, plural: string) {
  if (count === 1) {
    return singular;
  }
  return plural;
}

/**
 * One label per day, or per `everyDays` days for a weekly series. Days are counted in UTC so the
 * server and the browser write the same label.
 */
export function dayLabelsOf(firstDay: string, count: number, everyDays = 1) {
  const start = Date.parse(`${firstDay}T00:00:00Z`);
  const stride = everyDays * MS_PER_DAY;
  return Array.from({ length: count }, (_, index) => {
    const elapsed = index * stride;
    return DAY.format(start + elapsed);
  });
}

import { columnCenterOf, lerp, ratioOf, type Domain } from './scale';

export type Point = {
  x: number;
  y: number;
};

/** Paths are drawn in a box this wide and stretched to the plot, so a change of width never redraws them. */
export const VIEW_WIDTH = 1000;

function commandOf(point: Point, index: number) {
  const x = point.x.toFixed(1);
  const y = point.y.toFixed(1);
  if (index === 0) {
    return `M${x} ${y}`;
  }
  return `L${x} ${y}`;
}

export function linePathOf(points: readonly Point[]) {
  const commands = points.map((point, index) => commandOf(point, index));
  return commands.join(' ');
}

/** The line closed down (or up) to a level, for the wash under a line. */
export function areaPathOf(points: readonly Point[], levelY: number) {
  if (points.length === 0) {
    return '';
  }
  const line = linePathOf(points);
  const lastIndex = points.length - 1;
  const firstX = points[0].x.toFixed(1);
  const lastX = points[lastIndex].x.toFixed(1);
  const level = levelY.toFixed(1);
  return `${line} L${lastX} ${level} L${firstX} ${level} Z`;
}

/** The surface between two lines that share their x positions, for a range around a line. */
export function bandPathOf(upper: readonly Point[], lower: readonly Point[]) {
  if (upper.length === 0) {
    return '';
  }
  const backwards = [...lower].reverse();
  const outline = [...upper, ...backwards];
  const line = linePathOf(outline);
  return `${line} Z`;
}

/** The pixel height of a value in a plot: the top of the domain is 0, its bottom is the plot height. */
export function yOf(value: number, domain: Domain, height: number) {
  const ratio = ratioOf(value, domain);
  const fromBottom = ratio * height;
  return height - fromBottom;
}

/** One point per value, each in the middle of its column. */
export function plotPointsOf(
  values: readonly number[],
  domain: Domain,
  height: number
): Point[] {
  return values.map((value, index) => {
    const share = columnCenterOf(index, values.length);
    const x = share * VIEW_WIDTH;
    const y = yOf(value, domain, height);
    return { x, y };
  });
}

/** How many of the pieces lie before a segment when they are shared out evenly. */
function piecesBefore(
  segment: number,
  segmentCount: number,
  pieceCount: number
) {
  const share = segment / segmentCount;
  return Math.floor(share * pieceCount);
}

/**
 * The same line through exactly `count` points: each segment is cut into equal parts, so two lines
 * of different lengths share one structure and one can glide into the other.
 */
export function densifyOf(points: readonly Point[], count: number): Point[] {
  const segmentCount = points.length - 1;
  const hasSegments = segmentCount >= 1;
  const hasRoom = count > points.length;
  if (!hasSegments || !hasRoom) {
    return [...points];
  }
  const pieceCount = count - 1;
  const dense: Point[] = [points[0]];
  for (let segment = 0; segment < segmentCount; segment += 1) {
    const from = points[segment];
    const to = points[segment + 1];
    const start = piecesBefore(segment, segmentCount, pieceCount);
    const end = piecesBefore(segment + 1, segmentCount, pieceCount);
    const parts = end - start;
    for (let part = 1; part <= parts; part += 1) {
      const amount = part / parts;
      const x = lerp(from.x, to.x, amount);
      const y = lerp(from.y, to.y, amount);
      dense.push({ x, y });
    }
  }
  return dense;
}

